CREATE TABLE dbo.Users (
  Id int IDENTITY(1, 1) PRIMARY KEY,
  Name nvarchar(100) NOT NULL,
  Email nvarchar(255) UNIQUE,
  Age int NULL,
  Active bit NOT NULL DEFAULT 1,
  CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
);
CREATE TABLE dbo.Orders (
  Id int IDENTITY(1, 1) PRIMARY KEY,
  UserId int REFERENCES dbo.Users(Id),
  Amount decimal(12, 2) NOT NULL
);

SELECT STRING_AGG(CAST(Name AS nvarchar(max)), N', ') WITHIN GROUP (
  ORDER BY Id
)
FROM dbo.Users;

UPDATE u SET Active = 1
FROM dbo.Users u
JOIN (
  SELECT DISTINCT UserId
  FROM dbo.Orders
) o ON o.UserId = u.Id;

DECLARE @j nvarchar(max) = N'{"name":"Pomo","tags":["sql"]}';
SELECT JSON_VALUE(@j, '$.name'), JSON_QUERY(@j, '$.tags');
SELECT *
FROM OPENJSON(@j, '$.tags');

CREATE OR ALTER PROCEDURE dbo.GetUser @Id int AS
BEGIN
  SET NOCOUNT ON;
  SELECT *
  FROM dbo.Users
  WHERE Id = @Id;
END;

SET XACT_ABORT ON;
BEGIN TRY
  BEGIN TRANSACTION;
  UPDATE dbo.Users SET Active = 0
  WHERE Id = 1;
  COMMIT TRANSACTION;
END TRY
BEGIN CATCH
  IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;

SET STATISTICS IO ON;
SET STATISTICS TIME ON;
SELECT *
FROM dbo.Users
WHERE Id = 1;
SET STATISTICS IO OFF;
SET STATISTICS TIME OFF;
